from dataclasses import dataclass, field

@dataclass
class Step:
    sid: str
    agent: str
    parent: str | None
    evidence_ids: set[str]                  # 本步工具返回中真实存在的资源 id
    claims: list[dict]                      # {"text": str, "cites": [id]}
    contract_errors: list[str] = field(default_factory=list)

def ungrounded(step: Step) -> list[str]:
    bad = set()
    for c in step.claims:
        bad |= {cid for cid in c["cites"] if cid not in step.evidence_ids}
    return sorted(bad)

def blame(trace: list[Step], failed_sid: str) -> list[dict]:
    by_id = {s.sid: s for s in trace}
    chain, cur = [], by_id[failed_sid]
    while cur:
        chain.append(cur)
        cur = by_id.get(cur.parent) if cur.parent else None
    hits = []
    for s in reversed(chain):               # 源头 -> 失败点，最上游优先
        if s.contract_errors:
            hits.append({"sid": s.sid, "agent": s.agent,
                         "kind": "contract", "detail": s.contract_errors[:3]})
        miss = ungrounded(s)
        if miss:
            hits.append({"sid": s.sid, "agent": s.agent,
                         "kind": "ungrounded", "detail": miss[:3]})
    return hits

def attribute(trace, failed_sid, replay_fixed):
    hits = blame(trace, failed_sid)
    if not hits:
        return {"root_cause": None,
                "note": "契约与引用均通过，优先排查外部依赖与超时"}
    top = hits[0]
    recovered = replay_fixed(top["sid"])   # 用修正输出重放下游
    return {"root_cause": top, "confirmed": recovered,
            "amplifiers": [h["sid"] for h in hits[1:]]}

from dataclasses import dataclass
import urllib.parse

ALLOW = {
    "kb-server": {"search_docs": {"path_prefix": "/kb/public"}},
    "crm-server": {"get_ticket": {}},
}
SENSITIVE = {"read_secret", "export_file"}
EGRESS = {"http_post", "send_email", "upload"}

@dataclass
class Call:
    server: str
    tool: str
    args: dict
    turn_tools: list[str]

def check(call: Call) -> tuple[bool, str]:
    tools = ALLOW.get(call.server)
    if not tools or call.tool not in tools:
        return False, "tool_not_allowed"
    prefix = tools[call.tool].get("path_prefix", "/")
    path = call.args.get("path", "")
    if path and not path.startswith(prefix):
        return False, "path_escape"
    url = call.args.get("url")
    if url and urllib.parse.urlparse(url).hostname not in {"kb.internal"}:
        return False, "egress_blocked"
    used = set(call.turn_tools)
    if used & SENSITIVE and used & EGRESS:
        return False, "needs_human_approval"
    return True, "ok"

import threading

class Turn:
    def __init__(self, tid):
        self.tid = tid
        self.cancel = threading.Event()
        self.vad_hits = 0

class VoiceSession:
    def __init__(self):
        self.seq = 0
        self.turn = Turn(0)
        self.tts_playing = False

    def new_turn(self):
        self.turn.cancel.set()
        self.seq += 1
        self.turn = Turn(self.seq)
        return self.turn

    def on_vad(self, energy, asr_conf, keyword=False):
        th = 0.75 if self.tts_playing else 0.55
        if energy < th or asr_conf < 0.6:
            self.turn.vad_hits = 0
            return False
        self.turn.vad_hits += 1
        return keyword or self.turn.vad_hits >= 3

    def run_tool(self, tool, args):
        if tool.interruptible and self.turn.cancel.is_set():
            raise RuntimeError("cancelled")
        out = tool.call(args)
        if self.turn.cancel.is_set() and not tool.interruptible:
            ledger.add(self.turn.tid, tool.name, args, out)
        return out

from dataclasses import dataclass

@dataclass
class ToolResult:
    status: str
    reason: str = ""
    items: list = None
    fingerprint: str = ""

def info_gain(prev, cur):
    if not prev:
        return len(cur.items or [])
    return len(set(map(str, cur.items)) - set(map(str, prev.items)))

def should_retry(prev, cur, streak, strategy_changed, budget_left):
    if not budget_left or cur.status == "error":
        return False, "budget_or_error"
    if cur.status != "empty":
        return False, "has_result"
    if cur.reason in ("unauthorized", "backend_degraded"):
        return False, "clarify_or_degrade"
    if not strategy_changed:
        return False, "same_strategy"
    if prev and cur.fingerprint == prev.fingerprint:
        return False, "same_fingerprint"
    if streak >= 2 and info_gain(prev, cur) == 0:
        return False, "no_progress"
    return True, "changed_strategy"

import asyncio, re

PRONOUN = re.compile(r"(它|这个|那个|这款|该型号|上面)")
REWRITE = """把追问改写成可独立检索的 query。只允许使用 slots 与 history 中已出现的实体，禁止新增。
slots={slots}\nhistory={history}\nutt={utt}\n输出 JSON: {{"query": str, "entities": [str]}}"""

def need_rewrite(utt, slots):
    return len(utt) <= 20 or bool(PRONOUN.search(utt)) or not slots.get("product")

async def safe_rewrite(utt, slots, history, llm, timeout=0.3):
    try:
        out = await asyncio.wait_for(
            llm.json(REWRITE.format(slots=slots, history=history, utt=utt)), timeout)
    except Exception:
        return utt, False
    known = {v for v in slots.values() if v} | {e for h in history for e in h["entities"]}
    drifted = bool(known) and any(e not in known for e in out["entities"])
    return out["query"], drifted

def rrf(lists, weights, k=30):
    s = {}
    for w, ids in zip(weights, lists):
        for r, d in enumerate(ids, 1):
            s[d] = s.get(d, 0.0) + w / (k + r)
    return sorted(s, key=s.get, reverse=True)

async def turn_retrieve(utt, slots, history, retr, llm):
    q, w = utt, 0.0
    if need_rewrite(utt, slots):
        q, drifted = await safe_rewrite(utt, slots, history, llm)
        w = 0.0 if drifted else 0.8
    a, b = await asyncio.gather(
        retr(utt, 20), retr(q, 20) if w else asyncio.sleep(0, result=[]))
    return rrf([a, b], [1.0, w])

def minmax(scores):              # 反例：单 query 内归一化，分母易塌缩
    lo, hi = min(scores), max(scores)
    return [0.0 if hi == lo else (s - lo) / (hi - lo) for s in scores]

def fixed_map(cos):              # dense：固定映射，跨 query 可比
    return max(0.0, (cos - 0.55) / 0.40)

def lex_norm(bm25, q_max):       # lexical：除以本 query 的 max，保留相对强弱
    return 0.0 if q_max <= 0 else bm25 / q_max

def fuse(dense, lex, alpha=0.7, floor_lex=0.05):
    m = {}
    for doc, s in dense:
        m[doc] = m.get(doc, 0.0) + alpha * fixed_map(s)
    q_max = max([s for _, s in lex], default=0.0)
    for doc, s in lex:
        v = lex_norm(s, q_max)
        if v >= floor_lex:
            m[doc] = m.get(doc, 0.0) + (1 - alpha) * v
    return sorted(m.items(), key=lambda x: -x[1])

def rrf(lists, k=30, weights=None):
    weights = weights or [1.0] * len(lists)
    s = {}
    for w, ids in zip(weights, lists):
        for r, d in enumerate(ids, 1):
            s[d] = s.get(d, 0.0) + w / (k + r)
    return sorted(s, key=s.get, reverse=True)

from fastapi import FastAPI
from fastapi.responses import StreamingResponse
from starlette.middleware.gzip import GZipMiddleware
from starlette.types import ASGIApp, Scope, Receive, Send

class SelectiveGZip:
    def __init__(self, app: ASGIApp):
        self.app = app
        self.gzip = GZipMiddleware(app, minimum_size=1024)

    async def __call__(self, scope: Scope, receive: Receive, send: Send):
        if scope.get('type') == 'http' and not scope.get('path', '').startswith('/v1/chat/stream'):
            return await self.gzip(scope, receive, send)
        return await self.app(scope, receive, send)

app = FastAPI()
app.add_middleware(SelectiveGZip)

@app.get('/v1/chat/stream')
async def stream():
    async def gen():
        yield 'data: first\n\n'
        yield 'data: second\n\n'
    return StreamingResponse(gen(), media_type='text/event-stream', headers={
        'Cache-Control': 'no-cache, no-transform',
        'X-Accel-Buffering': 'no',
    })
